"""Additional coverage for BILL-212 beyond finance's worked examples."""
import calendar
import unittest
from datetime import date, timedelta
from fractions import Fraction

from billing.calendar import add_months, cycle_bounds, cycle_length_days
from billing.catalog import Catalog, Plan
from billing.proration import Subscription, portion, prorate_change


class CalendarRegressionTest(unittest.TestCase):
    def test_zero_and_backward_month_shifts(self):
        self.assertEqual(add_months(date(2024, 2, 29), 0), date(2024, 2, 29))
        self.assertEqual(add_months(date(2026, 3, 31), -1), date(2026, 2, 28))
        self.assertEqual(add_months(date(2024, 2, 29), -12), date(2023, 2, 28))

    def test_month_end_cycles_across_calendar(self):
        # Exercise all anchor months, short months, leap years and a non-leap century.
        for year in (2023, 2024, 2099):
            for month in range(1, 13):
                for day in range(28, calendar.monthrange(year, month)[1] + 1):
                    anchor = date(year, month, day)
                    for interval, step in (("month", 1), ("year", 12)):
                        renewals = []
                        for k in range(6):
                            y, m = divmod(year * 12 + month - 1 + k * step, 12)
                            m += 1
                            renewals.append(date(y, m, min(day, calendar.monthrange(y, m)[1])))
                        for start, end in zip(renewals, renewals[1:]):
                            for on in (start, end - timedelta(days=1)):
                                with self.subTest(anchor=anchor, interval=interval, on=on):
                                    self.assertEqual(cycle_bounds(anchor, on, interval), (start, end))
                                    self.assertEqual(cycle_length_days(anchor, on, interval),
                                                     (end - start).days)

    def test_invalid_cycle_requests(self):
        with self.assertRaises(ValueError):
            cycle_bounds(date(2026, 1, 31), date(2026, 1, 30), "month")
        with self.assertRaises(ValueError):
            cycle_length_days(date(2026, 1, 31), date(2026, 2, 1), "week")


class ExactRoundingTest(unittest.TestCase):
    def test_rational_rounding_including_ties_and_large_prices(self):
        for amount in (-101, -3, -1, 0, 1, 3, 101, 10**80 + 3):
            for denominator in range(1, 33):
                for numerator in range(denominator + 1):
                    self.assertEqual(portion(amount, numerator, denominator),
                                     round(Fraction(amount * numerator, denominator)))

    def test_invalid_fractions(self):
        for numerator, denominator in ((0, 0), (0, -1), (-1, 3), (4, 3)):
            with self.assertRaises(ValueError):
                portion(100, numerator, denominator)


class ProrationRegressionTest(unittest.TestCase):
    def test_old_price_at_start_and_new_price_at_change(self):
        catalog = Catalog({
            "old": Plan("old", "Old", "month", "USD",
                        ((date(2000, 1, 1), 100), (date(2026, 2, 1), 900))),
            "new": Plan("new", "New", "month", "USD",
                        ((date(2000, 1, 1), 200), (date(2026, 2, 1), 300))),
        })
        anchor = date(2026, 1, 31)
        result = prorate_change(Subscription("s", "c", "old", anchor),
                                "new", date(2026, 2, 14), catalog)
        self.assertEqual((result.credit, result.charge, result.total), (50, 150, 100))
        self.assertEqual((result.new_anchor, result.next_renewal), (anchor, date(2026, 2, 28)))
        self.assertEqual([line.amount for line in result.lines], [-50, 150])

    def test_interval_changes_charge_full_price_and_reset_line_period(self):
        catalog = Catalog({
            "monthly": Plan("monthly", "Monthly", "month", "USD", ((date(2000, 1, 1), 7),)),
            "annual": Plan("annual", "Annual", "year", "USD", ((date(2000, 1, 1), 23),)),
        })
        cases = [
            ("monthly", "annual", date(2023, 12, 31), date(2024, 2, 29), date(2025, 2, 28), 7, 23),
            ("annual", "monthly", date(2024, 2, 29), date(2028, 1, 31), date(2028, 2, 29), 2, 7),
        ]
        for old, new, anchor, change, renewal, credit, charge in cases:
            with self.subTest(old=old):
                result = prorate_change(Subscription("s", "c", old, anchor), new, change, catalog)
                self.assertEqual((result.credit, result.charge), (credit, charge))
                self.assertEqual((result.new_anchor, result.next_renewal), (change, renewal))
                self.assertEqual(result.lines[0].period_end, result.period_end)
                self.assertEqual(result.lines[1].period_start, change)
                self.assertEqual(result.lines[1].period_end, renewal)
                self.assertEqual(sum(line.amount for line in result.lines), result.total)
